package com.eldenworld.core.balance;
import com.eldenworld.core.EldenWorldCore; import com.eldenworld.core.requirements.RequirementChecker; import net.minecraft.resources.ResourceLocation; import net.minecraft.server.level.ServerLevel; import net.minecraft.server.level.ServerPlayer; import net.minecraft.world.entity.LivingEntity; import net.minecraft.world.entity.ai.attributes.*; import net.minecraft.world.entity.monster.Monster; import net.minecraftforge.event.entity.EntityJoinLevelEvent; import net.minecraftforge.eventbus.api.SubscribeEvent; import net.minecraftforge.fml.common.Mod; import net.minecraftforge.registries.ForgeRegistries; import java.util.*;
@Mod.EventBusSubscriber(modid=EldenWorldCore.MOD_ID) public final class WorldScalingEvents {static final UUID H=UUID.fromString("d39cbdd2-54f4-4f62-ae92-c99b57ea1f50"),D=UUID.fromString("fb80b080-c08c-4a8d-b105-3319d2f5e02a"),A=UUID.fromString("a6d87c9e-3490-4370-a9a7-fef9180e0cb3"); private WorldScalingEvents(){}
@SubscribeEvent public static void join(EntityJoinLevelEvent e){if(!(e.getLevel() instanceof ServerLevel l)||!(e.getEntity() instanceof Monster m)||m.isNoAi())return;List<ServerPlayer> ps=l.getEntitiesOfClass(ServerPlayer.class,m.getBoundingBox().inflate(64));if(ps.isEmpty())return;double sum=0;int c=0;for(ServerPlayer p:ps)try{sum+=Math.min(100,Math.max(0,RequirementChecker.pstLevel(p)));c++;}catch(RuntimeException ignored){}if(c==0)return;double level=sum/c;if(level<10)return;double pr=curve(level);Tier t=tier(m,m.getMaxHealth());mul(m.getAttribute(Attributes.MAX_HEALTH),H,"EldenWorld M5F world HP",pr*t.hp);mul(m.getAttribute(Attributes.ATTACK_DAMAGE),D,"EldenWorld M5F world damage",pr*t.damage);add(m.getAttribute(Attributes.ARMOR),A,"EldenWorld M5F world armor",pr*t.armor);m.setHealth(m.getMaxHealth());}
static double curve(double lv){if(lv<=20)return .20*(lv-10)/10.0;if(lv<=40)return .20+.25*(lv-20)/20.0;if(lv<=60)return .45+.25*(lv-40)/20.0;if(lv<=80)return .70+.20*(lv-60)/20.0;return .90+.10*(lv-80)/20.0;}
static Tier tier(LivingEntity m,double hp){ResourceLocation id=ForgeRegistries.ENTITY_TYPES.getKey(m.getType());String ns=id==null?"":id.getNamespace().toLowerCase(Locale.ROOT),p=id==null?"":id.getPath().toLowerCase(Locale.ROOT);boolean named=p.contains("boss")||p.contains("leviathan")||p.contains("ignis")||p.contains("harbinger")||p.contains("wither")||p.contains("warden")||p.contains("dragon")||p.contains("lich")||p.contains("hydra")||p.contains("naga")||p.contains("ur_ghast")||p.contains("snow_queen")||p.contains("ferrous_wroughtnaut")||p.contains("frostmaw");boolean bossMod=ns.contains("cataclysm")||ns.contains("mowzie")||ns.contains("aquamirae")||ns.contains("legendary")||ns.contains("block_factory")||ns.contains("twilightforest");boolean dangerous=ns.contains("born_in_chaos")||ns.contains("alexscaves")||ns.contains("iceandfire")||ns.contains("alexsmobs");if(hp>=180||named||(bossMod&&hp>=100))return new Tier(.10,.06,1.5);if(hp>=80||bossMod)return new Tier(.18,.10,2.5);if(hp>=45||dangerous)return new Tier(.28,.14,3.0);return new Tier(.42,.20,4.0);}static void mul(AttributeInstance a,UUID id,String n,double x){if(a!=null&&a.getModifier(id)==null&&x>0)a.addPermanentModifier(new AttributeModifier(id,n,x,AttributeModifier.Operation.MULTIPLY_BASE));}static void add(AttributeInstance a,UUID id,String n,double x){if(a!=null&&a.getModifier(id)==null&&x>0)a.addPermanentModifier(new AttributeModifier(id,n,x,AttributeModifier.Operation.ADDITION));}record Tier(double hp,double damage,double armor){}}
